// templategen draws the starter content of a new OMugen game: Proto, the
// template fighter (sprites, palettes and animations with collision boxes
// computed from its limbs), and the Proto Arena stage. Everything is
// generated from code, so the template has no third-party art.
//
// Run from the repo root: go run ./tools/templategen
//
// It writes the generated files next to the hand-written ones in
// templates/newgame (proto.def, proto.cns, proto.cmd, proto_arena.def...):
//
//	chars/proto/proto.sff, chars/proto/proto.air, stages/proto_arena.sff
package main

import (
	"bytes"
	"fmt"
	"image"
	"os"
	"path/filepath"
	"strings"

	"github.com/oakTINOoff/OMugen/src/sffwrite"
	"github.com/oakTINOoff/OMugen/tools/internal/art"
)

func check(err error) {
	if err != nil {
		panic(err)
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func writeFile(path string, data []byte) {
	check(os.MkdirAll(filepath.Dir(path), 0o755))
	check(os.WriteFile(path, data, 0o644))
	fmt.Printf("wrote %s (%.1f KB)\n", path, float64(len(data))/1024)
}

func main() {
	root := filepath.Join("templates", "newgame")
	pal := imagePalette(protoPalette(0))

	var sprites []sffwrite.Sprite
	seen := map[string]spriteKey{}
	addSprite := func(g, n int, img image.Image, ax, ay int) spriteKey {
		key := spriteKey{g, n}
		if p, ok := img.(*image.Paletted); ok {
			k := fmt.Sprintf("%dx%d@%d,%d:", p.Rect.Dx(), p.Rect.Dy(), ax, ay) + string(p.Pix)
			if old, ok := seen[k]; ok {
				return old
			}
			seen[k] = key
		}
		sprites = append(sprites, sffwrite.Sprite{Group: uint16(g), Number: uint16(n), AxisX: int16(ax), AxisY: int16(ay), Image: img})
		return key
	}

	var air strings.Builder
	air.WriteString("; Proto animations. Generated by tools/templategen: sprites and collision\n")
	air.WriteString("; boxes come from the same skeleton, so edit the poses there, or replace\n")
	air.WriteString("; this file with your own animations.\n")

	anims := protoAnims()
	checkAnimsEnd(anims)
	for _, a := range anims {
		var frames []airFrame
		for i, f := range a.frames {
			r := render(f.pose, 1, pal)
			key := addSprite(a.no, i, r.img, r.axisX, r.axisY)
			af := airFrame{spr: key, time: f.time, hurt: hurtBoxes(r.parts)}
			if f.hit != "" {
				af.hits = hitBoxes(r.parts, f.hit, f.beam)
			}
			frames = append(frames, af)
		}
		writeAir(&air, a.no, frames, a.loop)
	}

	// Effects: projectile, impact, super beam and hand flare (trans = add).
	fxAnim := func(no, n, t int, img func(int) *image.NRGBA, ax, ay int, clsn *box, lastTime int) {
		var frames []airFrame
		for i := 0; i < n; i++ {
			key := addSprite(no, i, img(i), ax, ay)
			f := airFrame{spr: key, time: t, trans: "A"}
			if clsn != nil {
				f.hits = []box{*clsn}
				f.hurt = []box{*clsn}
			}
			if i == n-1 && lastTime != 0 {
				f.time = lastTime
			}
			frames = append(frames, f)
		}
		writeAir(&air, no, frames, -1)
	}
	fxAnim(1005, 4, 3, orb, 64, 64, &box{-30, -30, 30, 30}, 0)
	fxAnim(1006, 5, 3, burst, 100, 100, nil, 3)
	fxAnim(3005, 3, 2, beam, 0, 90, nil, 0)
	fxAnim(3006, 3, 2, flare, 110, 110, nil, 0)

	small, big := portraits(pal)
	addSprite(9000, 0, small, 0, 0)
	addSprite(9000, 1, big, 0, 0)

	var palettes []sffwrite.Palette
	for i := range protoColors {
		palettes = append(palettes, sffwrite.Palette{Group: 1, Number: uint16(i + 1), Colors: protoPalette(i)})
	}
	var b bytes.Buffer
	check(sffwrite.WriteWithPalettes(&b, sprites, palettes))
	writeFile(filepath.Join(root, "chars", "proto", "proto.sff"), b.Bytes())
	writeFile(filepath.Join(root, "chars", "proto", "proto.air"), []byte(strings.ReplaceAll(air.String(), "\n", "\r\n")))
	fmt.Printf("  %d animations, %d sprites\n", len(anims)+4, len(sprites))

	var st []sffwrite.Sprite
	for _, s := range stageSprites() {
		st = append(st, sffwrite.Sprite{Group: uint16(s.g), Number: uint16(s.n), AxisX: int16(s.ax), AxisY: int16(s.ay), Image: s.img})
	}
	b.Reset()
	check(sffwrite.Write(&b, st))
	writeFile(filepath.Join(root, "stages", "proto_arena.sff"), b.Bytes())

	if path := os.Getenv("TEMPLATEGEN_SHEET"); path != "" {
		contactSheet(path, anims, pal)
	}
	if dir := os.Getenv("TEMPLATEGEN_PREVIEW"); dir != "" {
		check(os.MkdirAll(dir, 0o755))
		for _, s := range sprites {
			if s.Number == 0 || s.Group >= 1000 {
				art.WritePNG(filepath.Join(dir, fmt.Sprintf("%d_%d.png", s.Group, s.Number)), s.Image)
			}
		}
		for _, s := range st {
			art.WritePNG(filepath.Join(dir, fmt.Sprintf("stage_%d_%d.png", s.Group, s.Number)), s.Image)
		}
	}
}
